/**
 * Dither tile geometry — pure data, no React, no DOM.
 * Shared by <DitherPattern /> (SVG) and scripts/build-dither-css.ts (CSS mask utilities),
 * so the texture is identical everywhere.
 *
 * Spec (tokens.json → dither):
 * - regular  : 2px dots on a 6px grid, odd rows offset by 3px
 * - fine     : 2px dots on a 4px grid, odd rows offset by 2px
 * - bayer    : 4×4 ordered dither, 4px cells, threshold 0.32
 * - gradient : 4×4 ordered dither, density fades 0.68 → 0.06 top to bottom
 * - organic  : seamless 96px tile from periodic noise, clumps and gaps, 2px dots on a 4px grid
 *
 * Every dot in the system is DITHER_DOT (2px), the organic tile's size (Pierre).
 *              (the static sibling of the organic canvas texture)
 */


export type DitherVariant = "regular" | "fine" | "bayer" | "gradient" | "organic";

/** The one dot size of the whole system, and the organic grid step (Pierre: the organic tile is the base). */
export const DITHER_DOT = 2;
export const DITHER_CELL = 4;

export const DITHER_VARIANTS: readonly DitherVariant[] = ["regular", "fine", "bayer", "gradient", "organic"];

export interface DitherDot {
  x: number;
  y: number;
  /** Per-dot side (organic tile); falls back to the tile's `dot`. */
  size?: number;
}

export interface DitherTile {
  width: number;
  height: number;
  /** Side of each square dot, in px. */
  dot: number;
  dots: DitherDot[];
}

/** Classic 4×4 Bayer index matrix (0–15). */
export const BAYER_4 = [
  [0, 8, 2, 10],
  [12, 4, 14, 6],
  [3, 11, 1, 9],
  [15, 7, 13, 5],
] as const;


/* ------------------------------------------------------------------ *
 * Noise primitives, shared with organic-field.ts (the canvas texture).
 * ------------------------------------------------------------------ */

/** 8×8 Bayer matrix, normalised thresholds in (0, 1). */
const BAYER_8 = (() => {
  const out: number[][] = [];
  for (let y = 0; y < 8; y++) {
    out.push([]);
    for (let x = 0; x < 8; x++) {
      const q = (y >> 2) * 2 + (x >> 2);
      out[y].push((4 * BAYER_4[y % 4][x % 4] + [0, 2, 3, 1][q] + 0.5) / 64);
    }
  }
  return out;
})();

export function bayer(col: number, row: number) {
  return BAYER_8[row & 7][col & 7];
}

/** Integer hash → [0, 1). Deterministic, seedable. */
export function hash(x: number, y: number, seed: number) {
  let h = (x * 374761393 + y * 668265263 + seed * 2147483647) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
}

export const smooth = (t: number) => t * t * (3 - 2 * t);
const clamp01 = (v: number) => (v < 0 ? 0 : v > 1 ? 1 : v);
/** Contrast curve: below lo = empty, above hi = full, dithered in between. */
export const band = (v: number, lo: number, hi: number) => smooth(clamp01((v - lo) / (hi - lo)));

/* ------------------------------------------------------------------ *
 * Seamless organic tile (static): for SVG patterns, CSS masks and small
 * marks (chart tracks, remaining capacity, the button glow). Periodic
 * value noise, so the tile repeats without a visible seam.
 * ------------------------------------------------------------------ */

/** Value noise that repeats every `period` cells: tiles seamlessly. */
export function periodicNoise(x: number, y: number, period: number, seed: number) {
  const xi = Math.floor(x);
  const yi = Math.floor(y);
  const tx = smooth(x - xi);
  const ty = smooth(y - yi);
  const w = (v: number) => ((v % period) + period) % period;
  const a = hash(w(xi), w(yi), seed);
  const b = hash(w(xi + 1), w(yi), seed);
  const c = hash(w(xi), w(yi + 1), seed);
  const d = hash(w(xi + 1), w(yi + 1), seed);
  return a + (b - a) * tx + (c - a) * ty + (a - b - c + d) * tx * ty;
}

function periodicFbm(x: number, y: number, period: number, seed: number) {
  let sum = 0;
  let amp = 0.5;
  let f = 1;
  for (let o = 0; o < 3; o++) {
    sum += amp * periodicNoise(x * f, y * f, period * f, seed + o * 17);
    f *= 2;
    amp *= 0.5;
  }
  return sum / 0.875;
}

interface OrganicTileDot {
  x: number;
  y: number;
  size: number;
}

export interface OrganicTile {
  size: number;
  dots: OrganicTileDot[];
}

/**
 * A square, seamless organic tile: clumps and gaps, dots growing with density.
 * `cell` is the grid step, `dot` the [sparse, dense] dot sides, `period` the number of noise
 * cells across the tile (more = smaller clumps).
 */
export function organicTile({ size = 96, cell = DITHER_CELL, dot = [DITHER_DOT, DITHER_DOT], period = 3, seed = 7 }: { size?: number; cell?: number; dot?: [number, number]; period?: number; seed?: number } = {}): OrganicTile {
  const dots: OrganicTileDot[] = [];
  const n = Math.round(size / cell);
  for (let row = 0; row < n; row++) {
    for (let col = 0; col < n; col++) {
      const v = periodicFbm((col / n) * period, (row / n) * period, period, seed);
      // Keep a floor of sparse dots everywhere so tracks always read, clumps on top.
      const dens = 0.22 + band(v, 0.4, 0.75) * 0.36;
      if (dens <= bayer(col, row)) continue;
      const s = Math.round((dot[0] + (dot[1] - dot[0]) * Math.min(1, dens * 1.8)) * 4) / 4;
      const o = (cell - s) / 2;
      dots.push({ x: col * cell + o, y: row * cell + o, size: s });
    }
  }
  return { size, dots };
}

const BAYER_CELL = 4;
const BAYER_DOT = DITHER_DOT;
const BAYER_THRESHOLD = 0.32;
const GRADIENT_FROM = 0.68;
const GRADIENT_TO = 0.06;
/** Default height of the gradient tile (64 rows of 4px). */
export const GRADIENT_HEIGHT = 256;

function bayerOn(col: number, row: number, threshold: number) {
  return (BAYER_4[row % 4][col % 4] + 0.5) / 16 < threshold;
}

/** Centre a dot inside its cell so the grid reads evenly. */
const inset = (cell: number, dot: number) => (cell - dot) / 2;

export function ditherTile(variant: DitherVariant = "regular", gradientHeight = GRADIENT_HEIGHT): DitherTile {
  switch (variant) {
    case "regular":
    case "fine": {
      const cell = variant === "fine" ? 4 : 6;
      const dot = DITHER_DOT;
      const offset = cell / 2;
      return {
        width: cell,
        height: cell * 2,
        dot,
        dots: [
          { x: 0, y: 0 },
          { x: offset, y: cell },
        ],
      };
    }
    case "bayer": {
      const dots: DitherDot[] = [];
      for (let row = 0; row < 4; row++) {
        for (let col = 0; col < 4; col++) {
          if (bayerOn(col, row, BAYER_THRESHOLD)) {
            dots.push({
              x: col * BAYER_CELL + inset(BAYER_CELL, BAYER_DOT),
              y: row * BAYER_CELL + inset(BAYER_CELL, BAYER_DOT),
            });
          }
        }
      }
      return { width: BAYER_CELL * 4, height: BAYER_CELL * 4, dot: BAYER_DOT, dots };
    }
    case "organic": {
      const t = organicTile();
      return { width: t.size, height: t.size, dot: 2, dots: t.dots };
    }
    case "gradient": {
      const rows = Math.max(4, Math.round(gradientHeight / BAYER_CELL));
      const dots: DitherDot[] = [];
      for (let row = 0; row < rows; row++) {
        const t = GRADIENT_FROM - ((GRADIENT_FROM - GRADIENT_TO) * row) / (rows - 1);
        for (let col = 0; col < 4; col++) {
          if (bayerOn(col, row, t)) {
            dots.push({
              x: col * BAYER_CELL + inset(BAYER_CELL, BAYER_DOT),
              y: row * BAYER_CELL + inset(BAYER_CELL, BAYER_DOT),
            });
          }
        }
      }
      return { width: BAYER_CELL * 4, height: rows * BAYER_CELL, dot: BAYER_DOT, dots };
    }
  }
}

/** Standalone SVG markup of one tile, dots filled with `fill` (default black, for CSS masks). */
export function ditherTileSvg(variant: DitherVariant, fill = "#000") {
  const { width, height, dot, dots } = ditherTile(variant);
  const rects = dots.map((d) => `<rect x='${d.x}' y='${d.y}' width='${d.size ?? dot}' height='${d.size ?? dot}'/>`).join("");
  return `<svg xmlns='http://www.w3.org/2000/svg' width='${width}' height='${height}' fill='${fill}'>${rects}</svg>`;
}

import * as React from "react";

import { ditherTile, type DitherVariant } from "@/registry/dither/lib/dither-tile";
import { DitherPattern } from "@/registry/dither/lib/dither-pattern";
import { OrganicDither, type OrganicDitherProps, type OrganicShape } from "@/registry/dither/lib/organic-dither";
import { cn } from "@/registry/dither/lib/utils";

export type { DitherVariant } from "@/registry/dither/lib/dither-tile";
export type { OrganicShape } from "@/registry/dither/lib/organic-dither";

export { DitherPattern, type DitherPatternProps } from "@/registry/dither/lib/dither-pattern";

export interface DitherFillProps extends React.ComponentProps<"svg"> {
  variant?: DitherVariant;
  /** @deprecated Every DitherFill is animated now (drift + pointer wake). Kept for compatibility. */
  interactive?: boolean;
  /** Render the plain SVG tile, without the canvas animation (print, thumbnails). */
  static?: boolean;
  /** Gradient variant: height over which the density fades out (match the element height). */
  gradientHeight?: number;
  /**
   * Organic texture (canvas): density from a noise field instead of the tile.
   * cloud = masses and holes, scatter = dense on top with a ragged edge, halo = around the
   * content, flow = warped bands. Takes over `variant` / `interactive` when set.
   */
  shape?: OrganicShape;
  /** Organic only: noise scale (higher = smaller clumps). */
  scale?: number;
  /** Seed, to vary neighbouring panels. */
  seed?: number;
  /** Organic only: gradient tint (see OrganicDither). */
  tint?: OrganicDitherProps["tint"];
  /** Organic only: dot side range in px, [sparse, dense]. */
  dot?: [number, number];
  /** Organic only: soft edge, the texture (and glow) fades out instead of being cut. */
  fade?: DitherFade;
  /**
   * Organic only: blurred colour blobs under the dots, as custom property names
   * (e.g. ["--brand", "--chart-3"]). Dither and colour in blur, never a flat block.
   */
  glow?: string[];
}

export type DitherFade = "none" | "top" | "bottom" | "left" | "right" | "corner" | "edges";

/** CSS masks for the soft edges. "corner" keeps the top-right corner. */
export const ditherFadeMask: Record<DitherFade, string | undefined> = {
  none: undefined,
  top: "linear-gradient(to top, #000 35%, transparent)",
  bottom: "linear-gradient(to bottom, #000 35%, transparent)",
  left: "linear-gradient(to right, transparent, #000 55%)",
  right: "linear-gradient(to left, transparent, #000 55%)",
  corner: "radial-gradient(120% 120% at 100% 0%, #000 20%, transparent 70%)",
  edges: "radial-gradient(closest-side, #000 60%, transparent)",
};

const GLOW_SPOTS = [
  "left-[-10%] top-[-30%] h-[110%] w-[60%]",
  "right-[-10%] top-[-10%] h-[100%] w-[55%]",
  "left-[30%] bottom-[-40%] h-[90%] w-[50%]",
];

const DEFAULT_SCALE: Record<OrganicShape, number> = { cloud: 2.4, scatter: 3, halo: 3.2, flow: 1.6 };

/**
 * Fills its positioned parent with the texture.
 * - `shape`: organic texture (surfaces: heroes, cards, empty states, AI headers), with optional
 *   soft edge (`fade`) and blurred colour (`glow`).
 * - otherwise the tile `variant` (regular, fine, bayer, gradient, organic), animated the same way as
 *   the shapes: drifting noise and the pointer wake (canvas, still under reduced motion).
 *   `static` renders the plain SVG tile instead.
 */
export function DitherFill({ variant = "regular", gradientHeight, interactive: _interactive, static: isStatic = false, shape, scale, seed, tint, dot, fade = "none", glow, className, ...props }: DitherFillProps) {
  const id = `dither-${React.useId().replace(/[^a-zA-Z0-9-]/g, "")}`;
  if (shape) {
    const mask = ditherFadeMask[fade];
    return (
      <span
        aria-hidden="true"
        data-slot="dither-fill"
        className={cn("pointer-events-none absolute inset-0 overflow-hidden", className)}
        style={mask ? { maskImage: mask, WebkitMaskImage: mask } : undefined}
      >
        {glow?.map((color, i) => (
          <span
            key={color + i}
            className={cn("absolute rounded-full opacity-20 blur-3xl motion-safe:animate-[glow-float_14s_ease-in-out_infinite_alternate]", GLOW_SPOTS[i % GLOW_SPOTS.length])}
            style={{ background: `var(${color})`, animationDelay: `${i * -5}s` }}
          />
        ))}
        <OrganicDither shape={shape} scale={scale ?? DEFAULT_SCALE[shape]} seed={seed} tint={tint} dot={dot} />
      </span>
    );
  }
  if (!isStatic) {
    return (
      <span aria-hidden="true" data-slot="dither-fill" className={cn("pointer-events-none absolute inset-0 overflow-hidden", className)} style={props.style}>
        <OrganicDither tile={variant} gradientHeight={gradientHeight} seed={seed} />
      </span>
    );
  }
  return (
    <svg aria-hidden="true" className={cn("pointer-events-none absolute inset-0 size-full", className)} {...props}>
      <defs>
        <DitherPattern id={id} variant={variant} gradientHeight={gradientHeight} />
      </defs>
      <rect width="100%" height="100%" fill={`url(#${id})`} />
    </svg>
  );
}

/**
 * Organic dither field. Pure functions, no DOM.
 *
 * Instead of a fixed tile (regular grid, linear gradient), every cell of a pixel grid gets a
 * density between 0 and 1 from a *shape* (cloud, scatter, halo, flow) modulated by fractal
 * value noise. The cell is lit when its density beats an ordered (Bayer 8×8) threshold, so the
 * texture stays pixel-crisp but its density moves in clumps, wisps and holes.
 */

import { band, bayer, hash, smooth } from "@/registry/dither/lib/dither-tile";

export { bayer };

export type OrganicShape = "cloud" | "scatter" | "halo" | "flow";

export const ORGANIC_SHAPES: readonly OrganicShape[] = ["cloud", "scatter", "halo", "flow"];

/** 2D value noise in [0, 1]. */
export function valueNoise(x: number, y: number, seed = 1) {
  const xi = Math.floor(x);
  const yi = Math.floor(y);
  const tx = smooth(x - xi);
  const ty = smooth(y - yi);
  const a = hash(xi, yi, seed);
  const b = hash(xi + 1, yi, seed);
  const c = hash(xi, yi + 1, seed);
  const d = hash(xi + 1, yi + 1, seed);
  return a + (b - a) * tx + (c - a) * ty + (a - b - c + d) * tx * ty;
}

/** Fractal noise (4 octaves) in ~[0, 1]. */
export function fbm(x: number, y: number, seed = 1) {
  let sum = 0;
  let amp = 0.5;
  let f = 1;
  for (let o = 0; o < 4; o++) {
    sum += amp * valueNoise(x * f, y * f, seed + o * 17);
    f *= 2.03;
    amp *= 0.5;
  }
  return sum / 0.9375;
}


export interface FieldInput {
  /** Normalised position, 0..1 across the element. */
  u: number;
  v: number;
  /** Aspect ratio (w / h), so noise stays round on wide elements. */
  aspect: number;
  /** Time in seconds (drift). */
  t: number;
  seed: number;
  /** Noise scale: higher = smaller clumps. */
  scale: number;
}

/** Density 0..1 for one cell. */
export function density(shape: OrganicShape, { u, v, aspect, t, seed, scale }: FieldInput) {
  const nx = u * aspect * scale;
  const ny = v * scale;
  const drift = t * 0.06;
  switch (shape) {
    case "cloud": {
      // Billowy clumps with a slow domain warp: big soft masses and holes.
      const wx = fbm(nx * 0.6 + drift, ny * 0.6, seed + 3) - 0.5;
      const wy = fbm(nx * 0.6, ny * 0.6 - drift, seed + 7) - 0.5;
      const n = fbm(nx + wx * 1.6 + drift * 0.5, ny + wy * 1.6, seed);
      return band(n, 0.4, 0.66);
    }
    case "scatter": {
      // Dense at the top, breaking into a noisy, irregular edge and sparse grain below.
      const n = fbm(nx * 1.4 + drift, ny * 1.4, seed);
      const edge = 0.34 + (n - 0.5) * 0.7; // ragged boundary
      const fall = band(1 - (v - edge) * 2.2, 0.1, 0.9);
      // Below the edge: sparse grain that still follows the noise.
      const tail = band(n, 0.45, 0.8) * 0.32 * (1 - v * 0.6);
      return Math.max(fall, tail);
    }
    case "halo": {
      // A granular frame around the content: the centre stays empty whatever the box size
      // (distance measured in box-relative units), the dots gather towards the edges and corners.
      const dx = (u - 0.5) * 2;
      const dy = (v - 0.5) * 2;
      const r = Math.sqrt(dx * dx + dy * dy);
      const n = fbm(nx * 1.2 + drift, ny * 1.2 - drift, seed);
      return band(r + (n - 0.5) * 0.55, 0.78, 1.12);
    }
    case "flow": {
      // Warped bands, like a topographic field: stripes that thin and swell.
      const w = fbm(nx * 0.5 + drift, ny * 0.5, seed) * 6;
      const s = Math.sin((nx * 0.9 + ny * 1.4) * 3.4 + w);
      const n = fbm(nx * 2, ny * 2, seed + 11);
      return band(0.5 + s * 0.6 + (n - 0.5) * 0.6, 0.35, 0.8);
    }
  }
}

"use client";

import * as React from "react";

import { cn } from "@/registry/dither/lib/utils";
import { DITHER_CELL, DITHER_DOT, ditherTile, type DitherVariant } from "@/registry/dither/lib/dither-tile";
import { renderShapeGpu } from "@/registry/dither/lib/dither-gl";
import { bayer, density, fbm, valueNoise, type OrganicShape } from "@/registry/dither/lib/organic-field";

export type { OrganicShape } from "@/registry/dither/lib/organic-field";

export interface OrganicDitherProps extends React.ComponentProps<"canvas"> {
  shape?: OrganicShape;
  /**
   * Animate a tile instead of a shape: the tile's exact geometry (regular, fine, bayer, gradient,
   * organic), brought to life the same way as the shapes: a slowly drifting noise thins and refills
   * it, and the pointer leaves the same organic wake.
   */
  tile?: DitherVariant;
  /** Tile "gradient" only: height over which the density fades (defaults to the element height). */
  gradientHeight?: number;
  /** Grid cell in px (4 = the organic grid). */
  cell?: number;
  /** Dot side range in px. Default: the system dot (2px) everywhere, like the organic tile. */
  dot?: [number, number];
  /** Noise scale (higher = smaller clumps). */
  scale?: number;
  seed?: number;
  /** Drift speed (0 = still). */
  speed?: number;
  /** Cursor clears a soft hole in the field. */
  interactive?: boolean;
  /** CSS colour, defaults to --dither-color then --border-strong. */
  color?: string;
  /**
   * Tint the dots with a gradient instead of one colour. Stops are custom property names
   * (e.g. "--brand") or "transparent", read from the canvas so they follow the theme.
   */
  tint?: { stops: string[]; direction?: "to-r" | "to-l" | "to-b" };
}

/* One animation loop for every dither on the page: each instance registers a step that returns
   whether it still wants frames. Dozens of small canvases (chart tracks, legend swatches) then cost
   one requestAnimationFrame, not one each. Exported for the animated SVG pattern. */
type Step = (now: number) => boolean;
const steps = new Set<Step>();
let frame = 0;
function tick(now: number) {
  frame = 0;
  for (const step of steps) if (!step(now)) steps.delete(step);
  if (steps.size) frame = requestAnimationFrame(tick);
}
export function runDitherStep(step: Step) {
  steps.add(step);
  if (!frame) frame = requestAnimationFrame(tick);
}
export function stopDitherStep(step: Step) {
  steps.delete(step);
}

function readVar(el: HTMLElement, name: string) {
  if (!name.startsWith("--")) return name;
  return getComputedStyle(el).getPropertyValue(name).trim() || "transparent";
}

function readColor(el: HTMLElement, fallback?: string) {
  if (fallback) return fallback;
  const cs = getComputedStyle(el);
  return cs.getPropertyValue("--dither-color").trim() || cs.getPropertyValue("--border-strong").trim() || "#d3d3d3";
}

/**
 * Organic dither: a pixel grid whose density follows a noise field instead of a repeating tile
 * (masses, holes, ragged edges; dense areas get bigger dots). Drifts slowly; the pointer leaves an
 * organic wake (noisy edge, the texture thins out and regrows as grain, then heals). Pauses off-screen,
 * static under reduced motion. Fills its `relative` parent.
 * With `tile`, the same motion is applied to a tile's exact geometry, so every DitherFill moves alike.
 * Small data marks drawn with CSS / SVG (tracks, legends) keep the twinkling static tile.
 */
export function OrganicDither({
  shape = "cloud",
  tile,
  gradientHeight,
  cell = DITHER_CELL,
  dot = [DITHER_DOT, DITHER_DOT],
  scale = 3,
  seed: seedProp,
  speed = 1,
  interactive = true,
  color,
  tint,
  className,
  ...props
}: OrganicDitherProps) {
  const ref = React.useRef<HTMLCanvasElement>(null);
  // Tiles get a per-instance seed by default, so neighbouring panels don't drift in lockstep.
  const uid = React.useId();
  const seed = seedProp ?? (tile ? 7 + [...uid].reduce((a, c) => (a * 31 + c.charCodeAt(0)) % 9973, 0) : 7);
  const [d0, d1] = dot;
  const tintKey = tint ? `${tint.direction ?? "to-r"}:${tint.stops.join(",")}` : "";

  React.useEffect(() => {
    const canvas = ref.current;
    // Listen where the pointer actually lands: DitherFill wraps the canvas in a pointer-events-none
    // layer, so use that layer's parent (the surface the texture decorates).
    const host = (canvas?.closest("[data-slot=dither-fill]")?.parentElement ?? canvas?.parentElement) as HTMLElement | null;
    const ctx = canvas?.getContext("2d");
    if (!canvas || !host || !ctx) return;

    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    let w = 0;
    let h = 0;
    let dpr = 1;
    let fill = readColor(canvas, color);
    let last = 0;
    let visible = true;
    const start = performance.now();
    // Pointer trail: each point fades out; together they draw an organic wake, not a round hole.
    const trail: { x: number; y: number; life: number }[] = [];
    let lastPt = { x: -999, y: -999 };
    // Tile mode: every dot of the tile repeated over the canvas, computed on resize.
    let tileDots: { x: number; y: number; s: number }[] = [];
    const buildTile = () => {
      if (!tile) return;
      const t = ditherTile(tile, tile === "gradient" ? (gradientHeight ?? h) : undefined);
      const rows = tile === "gradient" ? 1 : Math.ceil(h / t.height);
      const cols = Math.ceil(w / t.width);
      const out: { x: number; y: number; s: number }[] = [];
      for (let r = 0; r < rows; r++)
        for (let c = 0; c < cols; c++)
          for (const d of t.dots) {
            const x = c * t.width + d.x;
            const y = r * t.height + d.y;
            if (x < w && y < h) out.push({ x, y, s: d.size ?? t.dot });
          }
      tileDots = out;
    };

    const paintTint = () => {
      if (!tint) return;
      const dir = tint.direction ?? "to-r";
      const g = dir === "to-b" ? ctx.createLinearGradient(0, 0, 0, h) : dir === "to-l" ? ctx.createLinearGradient(w, 0, 0, 0) : ctx.createLinearGradient(0, 0, w, 0);
      tint.stops.forEach((name, i) => g.addColorStop(i / Math.max(1, tint.stops.length - 1), readVar(canvas, name)));
      ctx.globalCompositeOperation = "source-in";
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, w, h);
      ctx.globalCompositeOperation = "source-over";
    };

    // Shared wake: how strongly the pointer trail stirs the point (x, y), with a frayed edge.
    const wakeAt = (x: number, y: number, t: number, r: number) => {
      let infl = 0;
      for (const pt of trail) {
        const dx = x - pt.x;
        const dy = y - pt.y;
        const d2 = dx * dx + dy * dy;
        if (d2 < r * r * 2.6) infl = Math.max(infl, pt.life * (1 - Math.sqrt(d2) / (r * 1.6)));
      }
      if (infl <= 0.02) return 0;
      const wobble = fbm(x * 0.02 + t * 0.4, y * 0.02, seed + 31);
      return Math.min(1, Math.max(0, infl * (0.6 + wobble * 0.9)));
    };

    const drawTile = (t: number) => {
      const r = Math.max(56, Math.min(w, h) * 0.3);
      const active = trail.length > 0;
      for (const d of tileDots) {
        // Two octaves of drifting noise: holes open, travel and close across the tile.
        let n = valueNoise(d.x * 0.03 + t * 0.25, d.y * 0.03 - t * 0.15, seed) * 0.62 + valueNoise(d.x * 0.08 - t * 0.4, d.y * 0.08 + t * 0.2, seed + 5) * 0.38;
        if (active) {
          const k = wakeAt(d.x, d.y, t, r);
          // Inside the wake the tile thins out, a few dots stay as loose grain.
          if (k > 0) n -= k * (0.75 + valueNoise(d.x * 0.2 - t, d.y * 0.2, seed + 9) * 0.5);
        }
        if (n < 0.32) continue;
        ctx.fillRect(d.x, d.y, d.s, d.s);
      }
    };

    const draw = (t: number) => {
      ctx.clearRect(0, 0, w, h);
      ctx.fillStyle = fill;
      if (tile) {
        drawTile(t);
        paintTint();
        return;
      }
      const r = Math.max(56, Math.min(w, h) * 0.3);
      // GPU first (one shared WebGL2 context for the page); the CPU loop below is the fallback.
      if (d0 === d1 && renderShapeGpu(ctx, { shape, w, h, dpr, cell, dot: d0, t, seed, scale, color: fill, trail, wakeRadius: r })) {
        paintTint();
        return;
      }
      const cols = Math.ceil(w / cell);
      const rows = Math.ceil(h / cell);
      const aspect = w / h;
      const active = trail.length > 0;
      for (let row = 0; row < rows; row++) {
        for (let col = 0; col < cols; col++) {
          const x = col * cell;
          const y = row * cell;
          let dens = density(shape, { u: (x + cell / 2) / w, v: (y + cell / 2) / h, aspect, t, seed, scale });
          if (active) {
            // Influence of the wake, with a noisy radius so its edge frays like the texture.
            let infl = 0;
            for (const pt of trail) {
              const dx = x - pt.x;
              const dy = y - pt.y;
              const d2 = dx * dx + dy * dy;
              if (d2 < r * r * 2.6) infl = Math.max(infl, pt.life * (1 - Math.sqrt(d2) / (r * 1.6)));
            }
            if (infl > 0.02) {
              const wobble = fbm(x * 0.02 + t * 0.4, y * 0.02, seed + 31);
              const k = Math.min(1, Math.max(0, infl * (0.6 + wobble * 0.9)));
              // Inside the wake the texture is stirred: it thins out and regrows as loose grain.
              const grain = fbm(x * 0.05 - t * 0.8, y * 0.05 + t * 0.5, seed + 53) * 0.55;
              dens = dens * (1 - k) + grain * k * (1 - k * 0.6);
            }
          }
          if (dens <= bayer(col, row)) continue;
          const s = Math.round((d0 + (d1 - d0) * dens * dens) * 2) / 2;
          const o = (cell - s) / 2;
          ctx.fillRect(x + o, y + o, s, s);
        }
      }
      paintTint();
    };

    const loop: Step = (now) => {
      if (!visible) return false;
      for (const pt of trail) pt.life *= 0.965;
      while (trail.length && trail[0].life < 0.03) trail.shift();
      if (now - last > 33) {
        last = now;
        draw(((now - start) / 1000) * speed);
      }
      return speed > 0 || trail.length > 0;
    };
    const wake = () => {
      if (!reduce) runDitherStep(loop);
    };

    const resize = () => {
      const rect = canvas.getBoundingClientRect();
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      w = Math.max(1, Math.round(rect.width));
      h = Math.max(1, Math.round(rect.height));
      canvas.width = w * dpr;
      canvas.height = h * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      fill = readColor(canvas, color);
      buildTile();
      draw(((performance.now() - start) / 1000) * speed);
    };

    const onMove = (e: PointerEvent) => {
      const rect = canvas.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      if (Math.hypot(x - lastPt.x, y - lastPt.y) < 10) return;
      lastPt = { x, y };
      trail.push({ x, y, life: 1 });
      if (trail.length > 28) trail.shift();
      wake();
    };
    const onLeave = () => {
      lastPt = { x: -999, y: -999 };
    };

    resize();
    const ro = new ResizeObserver(resize);
    ro.observe(canvas);
    const io = new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting;
      if (visible) wake();
    });
    io.observe(canvas);
    const mo = new MutationObserver(() => {
      fill = readColor(canvas, color);
      draw(((performance.now() - start) / 1000) * speed);
    });
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class", "style"] });
    if (interactive && !reduce) {
      host.addEventListener("pointermove", onMove);
      host.addEventListener("pointerleave", onLeave);
    }
    wake();
    return () => {
      stopDitherStep(loop);
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
      host.removeEventListener("pointermove", onMove);
      host.removeEventListener("pointerleave", onLeave);
    };
  }, [shape, tile, gradientHeight, cell, d0, d1, scale, seed, speed, interactive, color, tintKey]); // eslint-disable-line react-hooks/exhaustive-deps

  return <canvas ref={ref} aria-hidden="true" className={cn("pointer-events-none absolute inset-0 size-full", className)} {...props} />;
}

"use client";

import * as React from "react";

import { ditherTile, periodicNoise, type DitherVariant } from "@/registry/dither/lib/dither-tile";
import { runDitherStep, stopDitherStep } from "@/registry/dither/lib/organic-dither";

const DOT_FILL = "var(--dither-color, var(--border-strong))";
/** The animated pattern repeats every SIZE user units (a multiple of every tile size). */
const SIZE = 192;
/** Noise cells across SIZE for the two octaves (integers, so the noise tiles seamlessly). */
const P1 = 6;
const P2 = 16;

export interface DitherPatternProps {
  /** id referenced by `fill="url(#id)"`. Must be unique on the page. */
  id: string;
  variant?: DitherVariant;
  /** Height of the gradient tile in px (gradient variant only). */
  gradientHeight?: number;
}

/**
 * SVG `<pattern>` of the Dither texture, alive like every other dither: the tile's geometry,
 * thinned and refilled by slowly drifting noise, and stirred by the pointer (the same wake as
 * DitherFill). Place it inside `<defs>` and fill shapes with `url(#id)`. Dots use
 * `--dither-color`, falling back to `--border-strong`.
 *
 * The dots keep their on-screen size whatever the SVG's viewBox: a stretched SVG (a 100-unit
 * donut drawn at 180px) scales the pattern back, so a 2px dot stays 2px. Still under reduced motion.
 */
export function DitherPattern({ id, variant = "regular", gradientHeight }: DitherPatternProps) {
  const ref = React.useRef<SVGPatternElement>(null);
  const [scale, setScale] = React.useState(1);

  // One SIZE x SIZE block of the tile (gradient: one tile tall, SIZE wide).
  const { width, height, dots } = React.useMemo(() => {
    const t = ditherTile(variant, gradientHeight);
    const w = SIZE;
    const h = variant === "gradient" ? t.height : SIZE;
    const out: { x: number; y: number; s: number }[] = [];
    for (let ty = 0; ty < h; ty += t.height)
      for (let tx = 0; tx < w; tx += t.width) for (const d of t.dots) out.push({ x: tx + d.x, y: ty + d.y, s: d.size ?? t.dot });
    return { width: w, height: h, dots: out };
  }, [variant, gradientHeight]);

  React.useEffect(() => {
    const pattern = ref.current;
    const svg = pattern?.ownerSVGElement;
    if (!pattern || !svg) return;
    const rects = Array.from(pattern.children) as SVGRectElement[];
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const seed = 7 + [...id].reduce((a, c) => (a * 31 + c.charCodeAt(0)) % 9973, 0);
    let s = 1;
    let visible = true;
    let last = 0;
    const start = performance.now();
    const trail: { x: number; y: number; life: number }[] = [];

    const measure = () => {
      const vb = svg.viewBox.baseVal;
      const w = svg.getBoundingClientRect().width;
      s = vb && vb.width > 0 && w > 0 ? Math.round((vb.width / w) * 1000) / 1000 : 1;
      setScale(s);
    };

    const draw = (t: number) => {
      const r = 40;
      for (let i = 0; i < dots.length; i++) {
        const d = dots[i];
        let n = periodicNoise(((d.x + t * 8) / SIZE) * P1, ((d.y - t * 5) / SIZE) * P1, P1, seed) * 0.62 + periodicNoise(((d.x - t * 13) / SIZE) * P2, ((d.y + t * 6) / SIZE) * P2, P2, seed + 5) * 0.38;
        for (const pt of trail) {
          const dx = ((d.x - pt.x + SIZE * 1.5) % SIZE) - SIZE / 2;
          const dy = ((d.y - pt.y + SIZE * 1.5) % SIZE) - SIZE / 2;
          const dist = Math.hypot(dx, dy);
          if (dist < r) n -= pt.life * (1 - dist / r) * 0.9;
        }
        const on = n >= 0.32;
        const el = rects[i];
        if (el && (el.dataset.on === "1") !== on) {
          el.dataset.on = on ? "1" : "0";
          el.style.visibility = on ? "visible" : "hidden";
        }
      }
    };

    const step = (now: number) => {
      if (!visible) return false;
      for (const pt of trail) pt.life *= 0.965;
      while (trail.length && trail[0].life < 0.03) trail.shift();
      if (now - last > 33) {
        last = now;
        draw((now - start) / 1000);
      }
      return true;
    };
    const wake = () => {
      if (!reduce) runDitherStep(step);
    };

    const onMove = (e: PointerEvent) => {
      const m = svg.getScreenCTM();
      if (!m) return;
      const p = new DOMPoint(e.clientX, e.clientY).matrixTransform(m.inverse());
      // Into pattern space (patternTransform scales by s), wrapped to one block.
      const x = (((p.x / s) % SIZE) + SIZE) % SIZE;
      const y = (((p.y / s) % (variant === "gradient" ? height : SIZE)) + SIZE) % SIZE;
      const lastPt = trail[trail.length - 1];
      if (lastPt && Math.hypot(lastPt.x - x, lastPt.y - y) < 6) return;
      trail.push({ x, y, life: 1 });
      if (trail.length > 24) trail.shift();
      wake();
    };

    measure();
    draw(0);
    const ro = new ResizeObserver(measure);
    ro.observe(svg);
    const io = new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting;
      if (visible) wake();
    });
    io.observe(svg);
    const host = svg.parentElement ?? svg;
    if (!reduce) host.addEventListener("pointermove", onMove as EventListener);
    wake();
    return () => {
      stopDitherStep(step);
      ro.disconnect();
      io.disconnect();
      host.removeEventListener("pointermove", onMove as EventListener);
    };
  }, [id, dots, height, variant]);

  return (
    <pattern ref={ref} id={id} width={width} height={height} patternUnits="userSpaceOnUse" patternTransform={scale !== 1 ? `scale(${scale})` : undefined}>
      {dots.map((d) => (
        <rect key={`${d.x}-${d.y}`} x={d.x} y={d.y} width={d.s} height={d.s} style={{ fill: DOT_FILL }} />
      ))}
    </pattern>
  );
}
